import{c as t,Q as s,j as o,m as a}from"./chunks/framework.BqPkuuVc.js";const p=JSON.parse('{"title":"Exporting data","description":"","frontmatter":{},"headers":[],"relativePath":"user/after-the-event/exports.md","filePath":"user/after-the-event/exports.md"}'),n={name:"user/after-the-event/exports.md"};function r(i,e,l,h,d,c){return s(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="exporting-data" tabindex="-1">Exporting data <a class="header-anchor" href="#exporting-data" aria-label="Permalink to &quot;Exporting data&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers sharing results with federations, Eventor, or other systems.</p><p>How to export results and event data into the formats other systems expect.</p><blockquote><p><strong>Status:</strong> Stub — not yet written.</p></blockquote><h2 id="what-this-page-will-cover" tabindex="-1">What this page will cover <a class="header-anchor" href="#what-this-page-will-cover" aria-label="Permalink to &quot;What this page will cover&quot;">​</a></h2><ul><li>[ ] Exporting results as IOF XML</li><li>[ ] Exporting to Eventor</li><li>[ ] Exporting splits and tracking data</li><li>[ ] CSV exports for spreadsheet use</li><li>[ ] Archiving an event (self-contained backup of all its data)</li><li>[ ] What to do with the event folder after the competition</li></ul><h2 id="how-a-competitor-is-identified-in-an-exported-file" tabindex="-1">How a competitor is identified in an exported file <a class="header-anchor" href="#how-a-competitor-is-identified-in-an-exported-file" aria-label="Permalink to &quot;How a competitor is identified in an exported file&quot;">​</a></h2><p>Every results, start-list and entry-list export — IOF XML, OJSON and <strong>Upload to Eventor</strong> alike — names each competitor by the identifiers they hold: their <strong>Eventor ID</strong> (your own competitor number) and their <strong>IOF ID</strong>. In IOF XML the competitor number comes first and the IOF ID follows it marked as the IOF&#39;s, so a system that reads only the first one still finds the number it always did. A competitor holding neither is exported by name alone. The CSV entry and start lists carry both as the <strong>Database Id</strong> and <strong>IOF Id</strong> columns, and all of them read both back when imported into Manager.</p><p>To fill in IOF IDs for a field that arrived without them, see <a href="./../event-setup/import-event-data#importing-iof-ids">Importing IOF IDs</a>.</p><h2 id="exporting-one-country-s-results" tabindex="-1">Exporting one country&#39;s results <a class="header-anchor" href="#exporting-one-country-s-results" aria-label="Permalink to &quot;Exporting one country&#39;s results&quot;">​</a></h2><p><strong>Publish → Export IOF XML</strong> and <strong>Publish → Export JSON</strong> open a dialog that, alongside the classes, asks which <strong>Countries</strong> to include. Everything starts selected, so the file carries every country unless you untick some — handy when a national federation wants only its own runners.</p><ul><li>A competitor&#39;s country is their <strong>club&#39;s</strong>. A relay team goes by the team&#39;s own club, so a team is always exported whole.</li><li><strong>No country</strong> covers competitors whose club has no country recorded (or has a dash, <code>-</code>, where the code would be), and competitors with no club at all.</li><li>Places are not renumbered. A runner who came fourth in the class is fourth in the file, whoever else was left out.</li><li>The list only appears when there is more than one choice — a single country plus <strong>No country</strong> counts. The PDF, Print and <strong>Upload to Eventor</strong> actions don&#39;t offer it: Eventor must get every runner in each class you upload, or it reads the rest as never having entered.</li></ul><p>Each country shows with the code its clubs were given. If some clubs were given the IOC code (<code>SUI</code>) and others the ISO code (<code>CHE</code>), both appear — tick both.</p><h2 id="combining-classes-for-the-world-ranking-iof-xml" tabindex="-1">Combining classes for the World Ranking (IOF XML) <a class="header-anchor" href="#combining-classes-for-the-world-ranking-iof-xml" aria-label="Permalink to &quot;Combining classes for the World Ranking (IOF XML)&quot;">​</a></h2><p>The IOF asks a World Ranking event for a results file in which every class that ran a course is merged into one list and ordered — the ranking points are worked out over everyone on the course, not class by class. At a Middle where M21E and M20E run one course, and W21E and W20E another, that is two merged lists; at a sprint where M18A runs with them, three classes in each.</p><p><strong>Publish → Export IOF XML</strong> has an <strong>IOF XML options</strong> line for this: click <strong>Change</strong> beside it. In the dialog that opens, either click <strong>Combine by course</strong> — each set of the classes in the export that ran the same course becomes one combined class — or click <strong>Add combined class</strong> and pick its classes yourself. Click <strong>Done</strong>, check the line in Publish options now lists your combined classes, and export as usual. Nothing is remembered: the next export starts again with nothing combined.</p><ul><li>Each combined class is published once, with everyone in it ordered by time. <strong>Places and time behind are worked out across the combined list</strong>, so an M20E runner who beat half of M21E is placed among them.</li><li>Each combined class has a <strong>Class name</strong>, <strong>Class id</strong> and <strong>Course name</strong>. Left blank, the file uses its own: the class is named after its classes (<strong>M21E + M20E</strong>) with their ids joined (<strong>1+2</strong>), and the course after the class. Fill them in when the World Ranking event was set up with names of its own — <strong>Men</strong>, <strong>ME</strong> and so on. Two classes in one file can&#39;t have the same id; the dialog says so beside the field.</li><li>Nothing in the event changes. The classes stay separate everywhere else — on screen, in the JSON export, in the PDF and on Eventor. Export the ordinary file as well if anyone needs the classes apart.</li><li><strong>Combine by course</strong> counts classes as running the same course when they were given the same courses on the <strong>Classes</strong> page; a class alone on its course is left as it is. Only individual classes can be combined — never relay classes — and a class can be in one combined class only.</li><li>Classes you leave ticked but that aren&#39;t combined are exported as normal alongside — untick them from <strong>Classes</strong> if the IOF wants the World Ranking classes only. Untick a class you combined and it simply drops out of its combined class.</li></ul><h3 id="leaving-out-organisation-ids" tabindex="-1">Leaving out organisation ids <a class="header-anchor" href="#leaving-out-organisation-ids" aria-label="Permalink to &quot;Leaving out organisation ids&quot;">​</a></h3><p>The same dialog has <strong>Leave out organisation ids</strong>. Each competitor&#39;s club is still named in the file, with its country; only meshO&#39;s own number for the club is left out. That number means nothing to a system that numbers clubs its own way, such as the IOF World Ranking, which may otherwise try to match on it. A relay team&#39;s club keeps its id.</p><h2 id="exporting-the-entry-list" tabindex="-1">Exporting the entry list <a class="header-anchor" href="#exporting-the-entry-list" aria-label="Permalink to &quot;Exporting the entry list&quot;">​</a></h2><p>Who has entered — as opposed to when they start or how they got on — is exported from the <strong>Competitors</strong> page: <strong>Actions → Export entry list</strong>, in IOF XML, OJSON or CSV. It&#39;s written up where the menu lives: see <a href="./../event-setup/competitors-clubs-teams#exporting-the-entry-list">Exporting the entry list</a>.</p><p>Two things worth knowing before you reach for it:</p><ul><li><strong>The export is always the whole event</strong>, never the filtered list you&#39;re looking at.</li><li><strong>The CSV is designed to be edited and re-imported</strong> — though not every column comes back. The <a href="./../event-setup/competitors-clubs-teams#the-csv-round-trip">round-trip table</a> says which do.</li></ul><h2 id="exporting-a-multi-stage-event" tabindex="-1">Exporting a multi-stage event <a class="header-anchor" href="#exporting-a-multi-stage-event" aria-label="Permalink to &quot;Exporting a multi-stage event&quot;">​</a></h2><p>Both standings exports live on the <strong>Actions</strong> menu of the carnival&#39;s Standings tab, alongside Recompute.</p><p><strong>Overall standings as CSV</strong> — <strong>Export CSV</strong>. One row per competitor, one column per stage, plus the total: the shape a prize-giving spreadsheet wants. A stage that didn&#39;t count is bracketed rather than blanked, and a provisional total keeps its <code>*</code>, so the file says what the screen said. Export one class or all of them.</p><p><strong>Overall standings as PDF</strong> — <strong>Export PDF</strong>. The table laid out for printing or pinning up, matching whatever you have on screen: the class or combined view you have selected, and your Show and Times settings.</p><p><strong>IOF XML per stage</strong> — export a stage&#39;s results as IOF XML the usual way. Because the event is a stage, the file also carries the stage&#39;s <code>raceNumber</code> and each competitor&#39;s overall standing <em>after that stage</em> as an IOF <code>OverallResult</code>. Every stage up to it has to be settled first — a runner left with no status on an earlier day holds the file up, and the export tells you who (see <a href="./../reference/status-and-race-time#what-an-exported-results-file-contains">What an exported results file contains</a>). That is the IOF standard&#39;s own answer to multi-stage results, so SplitsBrowser, Eventor and Livelox read it with no bespoke format. A standalone event&#39;s export is unchanged.</p><p>See <a href="./../event-setup/multi-stage-events#exporting-a-carnival">Multi-stage events</a>.</p><blockquote><p><strong>A knock-out competition&#39;s classification has no export yet</strong> — it is on screen only. Each round&#39;s own results export normally, as any event&#39;s do. See <a href="./../event-setup/knock-out-competitions">Knock-out competitions</a>.</p></blockquote><h2 id="exporting-as-ojson" tabindex="-1">Exporting as OJSON <a class="header-anchor" href="#exporting-as-ojson" aria-label="Permalink to &quot;Exporting as OJSON&quot;">​</a></h2><p>Everything Manager exports as IOF XML it also exports as <strong>OJSON</strong> — a published format with a JSON Schema, carrying the things the XML has no room for: split-time columns as data, a relay team&#39;s own result, whether a split came from a card or a radio, and millisecond precision. If you are writing something that reads a Manager event — a club results page, a spreadsheet pipeline, an app — that is the format to read.</p><p>See <a href="./../advanced/orienteering-json">OJSON</a> for the endpoints, the field reference and the schema.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../advanced/orienteering-json">OJSON</a> — the format behind every <strong>Export JSON</strong> menu</li><li><a href="./results">Results</a></li><li><a href="./../event-setup/competitors-clubs-teams#exporting-the-entry-list">Competitors and clubs</a> — exporting the entry list</li><li><a href="./../event-setup/multi-stage-events">Multi-stage events</a> — exporting overall standings</li><li><a href="./../event-setup/import-event-data">Importing event data</a></li></ul>',35)])])}const u=t(n,[["render",r]]);export{p as __pageData,u as default};
